def _hist(y):
    f = MAC / f"fomc_{y}.html"
    if not f.exists():
        f.write_bytes(u.urlopen(u.Request(f"https://www.federalreserve.gov/monetarypolicy/fomchistorical{y}.htm", headers={"User-Agent": "Mozilla/5.0"}), timeout=30).read()); time.sleep(.3)
    return f.read_text(errors="ignore")


def fomc():
    D = []
    for y in range(2016, 2021):
        names = "|".join(MN)
        for m, ms, d1, m2, d2 in re.findall(rf"({names})(?:/({names}))?\s+([0-9]{{1,2}})(?:-(?:({names})\s+)?([0-9]{{1,2}}))?\s+Meeting", _hist(y)):
            D.append(pd.Timestamp(y, MN.index(m2 or ms or m) + 1, int(d2 or d1)))
        for _, m2, d2 in re.findall(r"\b([A-Z][a-z]{2})/([A-Z][a-z]{2})\s+[0-9]{1,2}-([0-9]{1,2})\s+Meeting", _hist(y)):  # labels like "Jan/Feb 31-1"
            D.append(pd.Timestamp(y, next(i for i, x in enumerate(MN) if x.startswith(m2)) + 1, int(d2)))
    t = (MAC / "fomc_now.html").read_text(errors="ignore")
    parts = re.split(r">\s*(20[0-9]{2}) FOMC Meetings\s*<", t)
    for y, body in zip(parts[1::2], parts[2::2]):
        for m, dd in re.findall(r'fomc-meeting__month[^>]*><strong>([A-Za-z/]+)</strong>.*?fomc-meeting__date[^>]*>\s*([0-9]{1,2}(?:-[0-9]{1,2})?)', body, flags=re.S):
            name = m.split("/")[-1]; mi = next(i for i, x in enumerate(MN) if x.startswith(name[:3]))
            D.append(pd.Timestamp(int(y), mi + 1, int(dd.split("-")[-1])))
    return pd.DatetimeIndex(sorted(set(D) - {pd.Timestamp("2025-08-22")}))  # that calendar row is not a rate-decision meeting


def calendar():
    return {"FOMC": fomc(), "CPI": pd.DatetimeIndex(CPI), "NFP": pd.DatetimeIndex(NFP), "PPI": pd.DatetimeIndex(PPI)}
